package vn.edu.fpt.seal.modules.incident.mapper;

import vn.edu.fpt.seal.modules.incident.dto.*; import vn.edu.fpt.seal.modules.incident.entity.*; import java.util.*;
public final class IncidentMapper { private IncidentMapper(){}
 public static IncidentResponse toResponse(IncidentReport i, List<IncidentEvidence> evidences, List<IncidentAction> actions){return IncidentResponse.builder().id(i.getId()).eventId(i.getEvent().getId()).trackId(i.getTrack()==null?null:i.getTrack().getId()).roundId(i.getRound()==null?null:i.getRound().getId()).teamId(i.getTeam()==null?null:i.getTeam().getId()).submissionId(i.getSubmission()==null?null:i.getSubmission().getId()).reporterId(i.getReporter().getId()).reporterEmail(i.getReporter().getEmail()).assignedCoordinatorId(i.getAssignedCoordinator()==null?null:i.getAssignedCoordinator().getId()).assignedCoordinatorEmail(i.getAssignedCoordinator()==null?null:i.getAssignedCoordinator().getEmail()).type(i.getType()).status(i.getStatus()).severity(i.getSeverity()).category(i.getCategory()).title(i.getTitle()).description(i.getDescription()).createdAt(i.getCreatedAt()).updatedAt(i.getUpdatedAt()).resolvedAt(i.getResolvedAt()).evidences(evidences.stream().map(IncidentMapper::toEvidenceResponse).toList()).actions(actions.stream().map(IncidentMapper::toActionResponse).toList()).build();}
 public static IncidentEvidenceResponse toEvidenceResponse(IncidentEvidence e){return IncidentEvidenceResponse.builder().id(e.getId()).incidentId(e.getIncident().getId()).fileUrl(e.getFileUrl()).externalUrl(e.getExternalUrl()).description(e.getDescription()).uploadedBy(e.getUploadedBy().getId()).uploadedByEmail(e.getUploadedBy().getEmail()).createdAt(e.getCreatedAt()).build();}
 public static IncidentActionResponse toActionResponse(IncidentAction a){return IncidentActionResponse.builder().id(a.getId()).incidentId(a.getIncident().getId()).actionBy(a.getActionBy().getId()).actionByEmail(a.getActionBy().getEmail()).actionType(a.getActionType()).targetType(a.getTargetType()).targetId(a.getTargetId()).oldValue(a.getOldValue()).newValue(a.getNewValue()).note(a.getNote()).createdAt(a.getCreatedAt()).build();}
}
